import { FunctionalComponent } from 'preact';
import { useDispatch } from 'react-redux';

import { getTranslation } from '../../../../../../../../shared/chromeApi';
import { clickedSupportUs, clickedCustomize } from '../../../../../slice';
import { MODALS } from '../../../../../../../../shared/utils/dict';

import styles from './../../styles.module.scss';

const NAV_LINKS = [
  {
    href:
      process.env.APP_TYPE === 'lite'
        ? 'https://docs.google.com/forms/d/e/1FAIpQLSeAiVXIzdoDfo5bmKgQUBcQ2Zg5mi6_gyzDxu9SBRgiKoXyng/viewform?usp=sf_link'
        : 'https://docs.google.com/forms/d/e/1FAIpQLScmPUPd1yQouSRETh51FYIk2BjewZOUnxAqJtyZme7xkR06fQ/viewform?usp=sf_link',
    translation: 'background_popup_option_feedback',
  },
  {
    href: 'https://oceanhero.zendesk.com/hc/en-us',
    translation: 'background_popup_option_help',
  },
  ...(process.env.TARGET_BROWSER === 'chrome'
    ? [
        {
          href: 'chrome://settings/manageProfile',
          translation: 'background_popup_option_theme_and_color',
        },
      ]
    : []),
  {
    href: 'https://about.oceanhero.today/bookmarks-extension',
    translation: 'background_popup_option_bookmarks',
  },
];

const CustomizePopupNav: FunctionalComponent = () => {
  const dispatch = useDispatch();

  const openModal = (): void => {
    dispatch(clickedSupportUs(MODALS.Patreon));
    dispatch(clickedCustomize());
  };

  return (
    <div className={styles.customizeNavigation}>
      <a className={styles.active}>
        {getTranslation('background_popup_option_customize')}
      </a>

      {NAV_LINKS.map(({ href, translation }) => (
        <a href={href} key={translation}>
          {getTranslation(translation)}
        </a>
      ))}

      <a className={styles.supportUs} onClick={openModal}>
        {getTranslation('background_popup_option_patreon')}
      </a>
    </div>
  );
};

export default CustomizePopupNav;
