import { FunctionalComponent } from 'preact';
import { useCallback, useState } from 'preact/hooks';

import CustomizeBasic from './CustomizeBasic';
import Expanded from './Expanded';
import { useDispatch, useSelector } from 'react-redux';
import { selectFeatureFlags } from '../../../../store/selectors';
import { openDragDrop } from '../../slice';

interface CustomizePopupProps {
  onClose: () => void;
  goBack: () => void;
}

const CustomizePopup: FunctionalComponent<CustomizePopupProps> = (
  props: CustomizePopupProps
) => {
  const { UI_EXTRA_MODES } = useSelector(selectFeatureFlags);
  const dispatch = useDispatch();
  const [modal, setModal] = useState(UI_EXTRA_MODES ? 'basic' : 'extended');

  const handleClickMore = useCallback((name) => {
    setModal('more');
    if (name === 'custom') {
      dispatch(openDragDrop());
    }
  }, []);

  // return modal === 'basic' ?
  //   <CustomizeBasic
  //     onClickMore={handleClickMore}
  //   /> :
  //   <Expanded {...props} />

  return <Expanded {...props} />;
};

export default CustomizePopup;
