import { FunctionalComponent,JSX } from 'preact';
import { useState, useEffect } from 'preact/hooks';
import {useDispatch, useSelector} from 'react-redux';
import { setCustomPicture, selectCustomPicture } from '../../../../../slice';
import { getTranslation } from '../../../../../../../../shared/chromeApi';
import StateIndicator from '../../../../../../../shared/StateIndicator';

import uploadIcon from '../../../../../../../../public/img/upload.svg';

import styles from './styles.module.scss';

const DragAndDrop: FunctionalComponent = () => {
  const dispatch = useDispatch();
  const [isDragging, setIsDragging] = useState(false);
  const customPicture = useSelector(selectCustomPicture);
  const [uploadState, setUploadState] = useState(null);

  useEffect(() => {
    setUploadState((prev) => {
      if (['success', 'failure'].includes(customPicture.uploadState)) {
        if (prev !== 'loading') return prev;
        setTimeout(() => {
          setUploadState(null);
        }, 5000);
      }

      return customPicture.uploadState;
    });

  }, [customPicture.uploadState]);

  const onCustomPictureSelect = ({
    currentTarget,
  }: JSX.TargetedEvent<HTMLInputElement, Event>): void => {
    dispatch(setCustomPicture(currentTarget));
  };

  const handleDragEnter = (e: DragEvent): void => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(true);
  };

  const handleDragLeave = (e: DragEvent): void => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);
  };

  const handleDragOver = (e: DragEvent): void => {
    e.preventDefault();
    e.stopPropagation();
  };

  const handleDrop = (e: DragEvent): void => {
    const imageTypeRegex = /[/](gif|jpe?g|png)$/i;
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);

    const file = e.dataTransfer.files[0];
    if (file && imageTypeRegex.test(file.type)) {
      dispatch(setCustomPicture(e.dataTransfer));
    }
  };

  if (uploadState) {
    const messsage = ({
      loading: 'Uploading and optimizing the picture for your screen',
      success: `Your picture was uploaded successfully`,
      error: `There was an error when uploading your picture`,
    })[uploadState];

    return (
      <div className={styles.dragDropContainer}>
        <div className={styles.dndZone}>
          <StateIndicator type={uploadState} message={messsage} />
        </div>
      </div>
    );
  }

  return (
    <div
      className={styles.dragDropContainer}
      onDragEnter={handleDragEnter}
      onDragLeave={handleDragLeave}
      onDragOver={handleDragOver}
      onDrop={handleDrop}
    >
      <div
        className={`${styles.dndZone} ${isDragging ? styles.highlight : ''}`}
      >
        <img src={uploadIcon} alt="" />
        <div className={styles.description}>
          {getTranslation('dnd_description')}
        </div>
        <div>{getTranslation('dnd_or')}</div>

        <label className={styles.browseFiles}>
          {getTranslation('dnd_browse_files')}
          <input
            type="file"
            data-value="custom"
            accept="image/png, image/jpeg"
            style="display: none"
            onChange={onCustomPictureSelect}
          />
        </label>

        <div className={styles.uploadGuidelines}>
          {getTranslation('dnd_file_description')}
        </div>
      </div>
    </div>
  );
};

export default DragAndDrop;
