import { FunctionalComponent } from 'preact';
import { useDispatch, useSelector } from 'react-redux';

import { getTranslation } from '../../../../../../../../shared/chromeApi';

import {
  changedMode,
  setGallery,
  openDragDrop,
  GalleryCategories,
  selectActiveBgCategory,
  selectUi,
  updateVideo,
  selectVideoBackground,
  fetchBackgrounds,
  selectedCollection,
} from '../../../../../slice';

import styles from './../../styles.module.scss';
import { thumbnails, categoryNames } from '../../shared';

import ArrowForwardIcon from '@material-ui/icons/ArrowForward';
import ToggleSwitch from '../../../../../../../../shared/ToggleSwitch';
import {
  selectIsAutofocus,
  setIsAutofocus,
} from '../../../../../../searchForm/slice';
import {
  getRandomVideo,
  getResolutionUrl,
  preloadPicture,
  // preloadVideo,
} from '../../../../../slice/utils';
import { useEffect, useState } from 'preact/hooks';
import { selectIsShowFeed, setIsShowFeed } from '../../../../../../user/slice';

const APP_PLATFORM = process.env.APP_PLATFORM;
const isExtension = APP_PLATFORM === 'extension';

const CustomizeOptions: FunctionalComponent = () => {
  const dispatch = useDispatch();
  const { mode } = useSelector(selectUi);
  const activeCategory = useSelector(selectActiveBgCategory);

  const isAutofocus = useSelector(selectIsAutofocus);
  const isShowFeed = useSelector(selectIsShowFeed);

  const [backgrounds, setBackgrounds] = useState(null);

  useEffect(() => {
    fetchBackgrounds().then(setBackgrounds);
  }, []);

  const handleCheck = (checked = !isAutofocus): void => {
    dispatch(setIsAutofocus(checked));
  };

  const handleShowFeed = (checked = !isShowFeed): void => {
    dispatch(setIsShowFeed(checked));
  };

  const onDarkModeClick = (): void => {
    dispatch(changedMode({ mode: 'dark' }));
    dispatch(updateVideo({ show: false }));
  };

  const onGalleryClick = (type: string): void => {
    dispatch(setGallery(type));
  };

  const onCustomPictureClick = (): void => {
    dispatch(openDragDrop());
  };

  const { videoBackground } = useSelector(selectVideoBackground);

  const fetchVideoFromPexels = async () => {
    if (videoBackground?.url) {
      dispatch(updateVideo({ show: true }));
      return;
    }

    const { url, newIndex, creditUrl, title, subtitle } =
      await getRandomVideo();

    dispatch(
      updateVideo({
        url: url,
        index: newIndex,
        show: true,
        title: title,
        credit: { title: subtitle, url: creditUrl },
      })
    );
  };

  const onCategorySelect = async (categoryName: string) => {
    if (categoryName === 'video') {
      fetchVideoFromPexels();
      return;
    }

    const randomIndex = Math.floor(
      Math.random() * backgrounds.categories[categoryName].length
    );

    const picture = backgrounds.categories[categoryName][randomIndex];

    await preloadPicture(
      getResolutionUrl(
        window.screen.width,
        backgrounds.resolutions,
        picture.url
      )
    );

    dispatch(
      selectedCollection({
        category: categoryName,
        now: Date.now(),
        ...(picture && {
          picture: {
            ...picture,
            originUrl: picture.url,
            url: getResolutionUrl(
              window.screen.width,
              backgrounds.resolutions,
              picture.url
            ),
          },
        }),
      })
    );

    dispatch(updateVideo({ show: false }));
  };

  // console.log('TARGET_BROWSER', process.env.TARGET_BROWSER);

  return (
    <div
      style={{
        overflow: 'hidden',
        display: 'flex',
        flexDirection: 'column',
        gap: '1rem',
      }}
    >
      {!(
        process.env.NODE_ENV === 'production' &&
        process.env.APP_PLATFORM === 'web'
      ) &&
        process.env.TARGET_BROWSER !== 'firefox' && (
          <div
            style={{
              display: 'flex',
              flexDirection: 'row',
              gap: '0.5rem',
              alignItems: 'center',
            }}
          >
            <p
              style={{ margin: 0, fontSize: '0.95rem' }}
              onClick={() => handleCheck()}
              className="text-white"
            >
              Always use the search box
            </p>

            <ToggleSwitch
              id="searchBarFocus"
              name="searchBarFocusToggle"
              checked={isAutofocus}
              onChange={(checked): void => handleCheck(checked)}
              className={styles.switch}
              size="medium"
            />
          </div>
        )}

      <div
        style={{
          display: 'flex',
          flexDirection: 'row',
          gap: '0.5rem',
          alignItems: 'center',
        }}
      >
        <p
          style={{ margin: 0, fontSize: '0.95rem' }}
          onClick={() => handleShowFeed()}
          className="text-white"
        >
          Show videos feed
        </p>

        <ToggleSwitch
          id="showFeed"
          name="showFeedToggle"
          checked={isShowFeed}
          onChange={(checked): void => handleShowFeed(checked)}
          className={styles.switch}
          size="medium"
        />
      </div>

      <div className={styles.customizeOptions}>
        {isExtension && window?.webkitRequestFileSystem && (
          <button
            onClick={onCustomPictureClick}
            className={`${styles.customizeOption} ${mode === 'custom' ? styles.active : ''
              }`}
          >
            <div
              className={styles.optionPreview}
              style="background: url('img/background/customize/ic-file-upload.svg') no-repeat center"
            />
            <span className={styles.optionTitle}>
              {getTranslation('background_popup_option_custom')}
            </span>
          </button>
        )}

        <button
          onClick={onDarkModeClick}
          className={`${styles.customizeOption} ${!videoBackground.show && mode === 'dark' ? styles.active : ''
            }`}
        >
          <div className={styles.optionPreview} style="background: #313639" />
          <span className={styles.optionTitle}>
            {getTranslation('background_popup_option_theme_dark')}
          </span>
        </button>

        <button
          onClick={() => onGalleryClick('video')}
          className={`${styles.customizeOption} ${videoBackground.show ? styles.active : ''
            }`}
        >
          <div
            className={`${styles.optionPreview} ${styles.noBorder}`}
            style={{ overflow: 'hidden' }}
          >
            <video
              style={{ objectFit: 'cover', height: '100%', width: '100%' }}
              autoPlay
              muted
              loop
              src={thumbnails['video']}
            />
          </div>
          <span className={styles.optionTitle}>Videos</span>
        </button>

        {GalleryCategories.map((categoryName) => (
          <button
            key={categoryName}
            onClick={() => onGalleryClick(categoryName)}
            className={`${styles.customizeOption} ${mode === 'gallery' &&
              activeCategory === categoryName &&
              !videoBackground.show
              ? styles.active
              : ''
              }`}
          >
            <div
              className={`${styles.optionPreview} ${styles.noBorder}`}
              style={`background-image: url('${thumbnails[categoryName]}')`}
            />
            <button
              className={styles.optionTitle}
              onClick={(e): void => {
                e.stopPropagation();
                onGalleryClick(categoryName);
              }}
            >
              {categoryNames[categoryName]}
            </button>
          </button>
        ))}
        <a
          href="https://docs.google.com/forms/d/e/1FAIpQLSedeGpfzMLt9qgUpuOy5HUPvc26ZqTLMWHAoanbqN3DoBa1Tg/viewform?usp=sf_link"
          className={styles.categorySurvey}
          target="_blank"
          rel="noreferrer"
        >
          <ArrowForwardIcon className={styles.arrow} />
          {getTranslation('add_categories_feedback')}
        </a>
      </div>
    </div>
  );
};

export default CustomizeOptions;
